security_headers();require_admin();
$db=database();$state=admin_activity_resolution($db);$activity=$state['activity'];if(!$activity){header('Location: /admin/activities.php');exit;}$activityId=(int)$activity['id'];
$courseId=(int)($_GET['course']??$_POST['course_id']??0);$course=$courseId>0?course_by_id($db,$courseId):null;if($course&&(int)$course['activity_id']!==$activityId)$course=null;
$view=(string)($_GET['view']??'overview');if(!in_array($view,['overview','setup','cohorts','students','lessons','material'],true))$view='overview';
function course_page_url(int $activityId,int $courseId=0,string $view='overview'): string {return $courseId>0?admin_course_url($activityId,$courseId,$view):'/admin/courses.php?'.http_build_query(['activity'=>$activityId]);}
function course_index_url(int $activityId,string $q='',int $page=1): string {$args=['activity'=>$activityId];if($q!=='')$args['q']=$q;if($page>1)$args['page']=$page;return '/admin/courses.php?'.http_build_query($args);}
function course_students_url(int $activityId,int $courseId,string $q='',int $page=1): string {$args=['activity'=>$activityId,'course'=>$courseId,'view'=>'students'];if($q!=='')$args['q']=$q;if($page>1)$args['page']=$page;return '/admin/courses.php?'.http_build_query($args);}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    if(!verify_csrf('courses-admin',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}$action=(string)($_POST['action']??'');
    try{
        if($action==='create_from_page'){$created=course_create_from_page($db,(int)($_POST['public_page_id']??0),(int)($_POST['registration_form_id']??0));$courseId=(int)$created['id'];$view='overview';}
        elseif(!$course)throw new RuntimeException('Escolha um curso.');
        elseif($action==='update_course')course_update($db,(int)$course['id'],$_POST);
        elseif($action==='create_cohort')course_create_cohort_for_course($db,(int)$course['id'],(string)($_POST['title']??''),(string)($_POST['slug']??''),(string)($_POST['starts_at']??'')?:null,(string)($_POST['ends_at']??'')?:null);
        elseif($action==='add_lesson')course_add_lesson_for_course($db,(int)$course['id'],(string)($_POST['title']??''),(string)($_POST['lesson_key']??''));
        elseif($action==='set_release')course_set_lesson_release_for_course($db,(int)$course['id'],(int)($_POST['cohort_id']??0),(int)($_POST['lesson_id']??0),(string)($_POST['mode']??'block'),(string)($_POST['scheduled_at']??''));
        elseif($action==='add_material')course_material_add_page($db,(int)$course['id'],(int)($_POST['page_id']??0));
        elseif($action==='remove_material')course_material_remove_page($db,(int)$course['id'],(int)($_POST['page_id']??0));
        elseif($action==='map_section')course_material_set_section_lesson($db,(int)$course['id'],(int)($_POST['page_id']??0),(string)($_POST['section_key']??''),(int)($_POST['lesson_id']??0)?:null);
        else throw new RuntimeException('Ação inválida.');
        $_SESSION['admin_notice']='Alteração salva.';
    }catch(Throwable $e){$_SESSION['admin_notice']='Não foi possível concluir: '.$e->getMessage();}
    header('Location: '.course_page_url($activityId,$courseId,$view),true,303);exit;
}
$pages=array_values(array_filter(cms_pages($db,$activityId,null,true),static fn(array $p): bool=>(string)$p['status']!=='archived'));$forms=array_values(array_filter(cms_forms($db,$activityId),static fn(array $f): bool=>cms_form_purpose($f)==='enrollment'));
$notice=(string)($_SESSION['admin_notice']??'');unset($_SESSION['admin_notice']);
admin_shell_start('courses','Cursos',$state);?>
<?php if($notice!==''):?><div class="admin-notice"><?=h($notice)?></div><?php endif;?>
<?php if(!$course):
$courseQ=trim((string)($_GET['q']??''));$coursePage=max(1,(int)($_GET['page']??1));$coursePageSize=25;$where=["c.activity_id=?","c.status!='archived'"];$args=[$activityId];if($courseQ!==''){$where[]='(c.title LIKE ? OR c.slug LIKE ? OR p.title LIKE ?)';$like='%'.$courseQ.'%';array_push($args,$like,$like,$like);}$whereSql=implode(' AND ',$where);
$count=$db->prepare("SELECT COUNT(*) FROM courses c LEFT JOIN cms_pages p ON p.id=c.public_page_id WHERE $whereSql");$count->execute($args);$courseTotal=(int)$count->fetchColumn();$coursePages=max(1,(int)ceil($courseTotal/$coursePageSize));if($coursePage>$coursePages)$coursePage=$coursePages;$courseOffset=($coursePage-1)*$coursePageSize;
$sql="SELECT c.*,p.title public_page_title,
(SELECT COUNT(*) FROM course_cohorts cc WHERE cc.course_id=c.id AND cc.status!='archived') cohorts,
(SELECT COUNT(*) FROM course_enrollments e JOIN course_cohorts cc ON cc.id=e.cohort_id WHERE cc.course_id=c.id AND cc.status!='archived' AND e.status='active') students,
(SELECT COUNT(*) FROM cms_form_submissions s WHERE s.course_id=c.id AND s.status!='archived') registrations,
(SELECT COUNT(*) FROM cms_form_submissions s WHERE s.course_id=c.id AND s.status!='archived' AND (s.payment_status='paid' OR s.status='converted') AND s.cohort_id IS NULL) unassigned
FROM courses c LEFT JOIN cms_pages p ON p.id=c.public_page_id WHERE $whereSql ORDER BY c.title COLLATE NOCASE,c.id LIMIT $coursePageSize OFFSET $courseOffset";$list=$db->prepare($sql);$list->execute($args);$courseRows=$list->fetchAll();?>
