<?php elseif($view==='material'):$materialPages=course_material_pages($db,$courseId);$lessons=course_lessons_for_course($db,$courseId);$materialIds=array_fill_keys(array_map(static fn(array $p): int=>(int)$p['id'],$materialPages),true);?>
<section class="admin-card"><header><div><h2>Material</h2><p>Material é uma visão contextual das mesmas páginas do CMS. Não existe editor ou conteúdo paralelo.</p></div><div class="admin-card-actions"><a class="admin-button secondary" href="/admin/pages.php?activity=<?=$activityId?>">Abrir Páginas</a></div></header><?php if(!$materialPages):?><div class="admin-empty">Nenhuma página associada.</div><?php endif;?><?php foreach($materialPages as $page):$sections=course_material_sections_from_page($db,(int)$page['id']);$map=course_material_section_map($db,$courseId,(int)$page['id']);?><section class="admin-card"><header><div><p class="admin-kicker">Página CMS</p><h3><?=h((string)$page['title'])?></h3></div><div class="admin-card-actions"><a class="admin-button secondary" href="/editor/?page=<?=(int)$page['id']?>">Editar página</a><form method="post" data-confirm="Remover esta página do material do curso? A página não será excluída."><input type="hidden" name="_csrf" value="<?=h(csrf_token('courses-admin'))?>"><input type="hidden" name="action" value="remove_material"><input type="hidden" name="course_id" value="<?=$courseId?>"><input type="hidden" name="page_id" value="<?=(int)$page['id']?>"><button class="admin-button secondary" type="submit">Desassociar</button></form></div></header><?php if(!$sections):?><div class="admin-empty compact">A página não possui seções CMS identificáveis no rascunho atual.</div><?php else:?><div class="admin-table-scroll"><table class="admin-data-table"><thead><tr><th>Seção</th><th>Liberação</th></tr></thead><tbody><?php foreach($sections as $key=>$label):$lessonId=(int)($map[$key]['lesson_id']??0);?><tr><td><strong><?=h($label)?></strong><div class="muted"><?=h($key)?></div></td><td><form class="admin-inline-actions" method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('courses-admin'))?>"><input type="hidden" name="action" value="map_section"><input type="hidden" name="course_id" value="<?=$courseId?>"><input type="hidden" name="page_id" value="<?=(int)$page['id']?>"><input type="hidden" name="section_key" value="<?=h($key)?>"><select name="lesson_id"><option value="0">Sempre disponível</option><?php foreach($lessons as $lesson):?><option value="<?=(int)$lesson['id']?>"<?=$lessonId===(int)$lesson['id']?' selected':''?>><?=h((string)$lesson['title'])?></option><?php endforeach;?></select><button class="admin-button secondary" type="submit">Salvar</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endforeach;?></section>
<section class="admin-card"><header><div><h2>Associar página existente</h2><p>A página permanece na biblioteca editorial global e continua usando o editor CMS normal.</p></div></header><form class="admin-form-grid" method="post"><input type="hidden" name="_csrf" value="<?=h(csrf_token('courses-admin'))?>"><input type="hidden" name="action" value="add_material"><input type="hidden" name="course_id" value="<?=$courseId?>"><label class="admin-form-span-2">Página<select name="page_id" required><option value="">Escolha</option><?php foreach($pages as $page):if(isset($materialIds[(int)$page['id']]))continue;?><option value="<?=(int)$page['id']?>"><?=h((string)$page['title'].' · '.public_language_label((string)$page['locale']))?></option><?php endforeach;?></select></label><div class="admin-form-actions"><button class="admin-button" type="submit">Associar ao material</button></div></form></section>
<?php endif;?>
<?php endif;?>
<?php admin_shell_end();
